# 1. Valid Registration
$reg1 = Invoke-RestMethod -Uri "http://127.0.0.1:8000/api/auth/register" -Method Post -ContentType "application/json" -Body '{"account_identifier": "test_student", "password": "student_password_123"}'
Write-Host "Register Success:" ($reg1 | ConvertTo-Json -Compress)

# 2. Duplicate Registration Rejection
try {
    Invoke-RestMethod -Uri "http://127.0.0.1:8000/api/auth/register" -Method Post -ContentType "application/json" -Body '{"account_identifier": "test_student", "password": "another_password"}'
} catch {
    Write-Host "Duplicate rejected as expected. Status:" $_.Exception.Response.StatusCode.value__ "Body:" $_.ErrorDetails.Message
}

# 3. Incomplete Registration Rejection
try {
    Invoke-RestMethod -Uri "http://127.0.0.1:8000/api/auth/register" -Method Post -ContentType "application/json" -Body '{"account_identifier": "  ", "password": "   "}'
} catch {
    Write-Host "Incomplete rejected as expected. Status:" $_.Exception.Response.StatusCode.value__ "Body:" $_.ErrorDetails.Message
}

# 4. Valid Login
$login = Invoke-RestMethod -Uri "http://127.0.0.1:8000/api/auth/login" -Method Post -ContentType "application/json" -Body '{"account_identifier": "test_student", "password": "student_password_123"}'
Write-Host "Login Success:" ($login | ConvertTo-Json -Compress)

# 5. Invalid Login Validation
try {
    Invoke-RestMethod -Uri "http://127.0.0.1:8000/api/auth/login" -Method Post -ContentType "application/json" -Body '{"account_identifier": "test_student", "password": "wrong_password"}'
} catch {
    Write-Host "Invalid login rejected as expected. Status:" $_.Exception.Response.StatusCode.value__ "Body:" $_.ErrorDetails.Message
}

